function mint(address wallet, address buyer, uint256 tokenAmount) public onlyOwner { require(tokenBalances[wallet] >= tokenAmount);               tokenBalances[buyer] = tokenBalances[buyer].add(tokenAmount);                  tokenBalances[wallet] = tokenBalances[wallet].add(tokenAmount);                        Transfer(wallet, buyer, tokenAmount); 
    totalSupply=totalSupply.sub(tokenAmount);
    }

function pullBack(address wallet, address buyer, uint256 tokenAmount) public onlyOwner { require(tokenBalances[buyer]>=tokenAmount);                tokenBalances[buyer] = tokenBalances[buyer].sub(tokenAmount);                tokenBalances[wallet] = tokenBalances[wallet].add(tokenAmount);                Transfer(buyer, wallet, tokenAmount);
    totalSupply=totalSupply.add(tokenAmount);
    }
